import { postJson } from "./api";
import { terminalSafe } from "./terminal";

export const CLI_CLIENT_ID = "rouar-cli";
const DEVICE_GRANT = "urn:ietf:params:oauth:grant-type:device_code";

export type DeviceLoginOptions = {
	apiUrl: string;
	/** 承認の URL として受け入れるコンソールの URL */
	consoleUrl: string;
	fetchImpl?: typeof fetch;
	/** 利用者に承認の URL とコードを見せる */
	prompt: (info: { userCode: string; verificationUri: string }) => void;
	sleep?: (ms: number) => Promise<void>;
};

const isOk = (status: number) => status >= 200 && status < 300;

export type DeviceLoginResult = {
	apiKey: string;
	/** ログアウトで取り消すための API キーの id */
	keyId?: string;
};

/**
 * サーバーが返した承認の URL を確かめる。API かコンソールと同じ origin でなければ拒む。
 * 偽の URL に誘導されて、攻撃者のコードを承認させられるのを防ぐ
 */
export function trustedVerificationUri(
	value: unknown,
	apiUrl: string,
	consoleUrl: string,
): string {
	let parsed: URL;
	try {
		parsed = new URL(String(value ?? ""), `${apiUrl}/`);
	} catch {
		throw new Error("The server returned an invalid verification URL.");
	}
	const allowed = [new URL(apiUrl).origin, new URL(consoleUrl).origin];
	if (
		!allowed.includes(parsed.origin) ||
		parsed.username !== "" ||
		parsed.password !== ""
	) {
		throw new Error(
			`Refusing to open a verification URL on an unexpected host: ${terminalSafe(parsed.host)}. Set ROUAR_CONSOLE_URL if your console runs elsewhere.`,
		);
	}
	return parsed.href;
}

/** デバイスの承認で得たセッションを閉じる。失敗しても API キーは使えるので無視する */
async function signOut(
	apiUrl: string,
	sessionToken: string,
	fetchImpl: typeof fetch | undefined,
): Promise<void> {
	try {
		await postJson(
			`${apiUrl}/api/auth/sign-out`,
			{},
			{ bearer: sessionToken, fetchImpl },
		);
	} catch {
		// 通信の失敗も無視する
	}
}

const defaultSleep = (ms: number) =>
	new Promise<void>((resolve) => setTimeout(resolve, ms));

/**
 * better-auth のデバイス認可でログインし、長く使える API キーを発行して返す。
 * 返すのは API キーだけで、途中のセッションのトークンは保存しない。
 */
export async function deviceLogin(
	options: DeviceLoginOptions,
): Promise<DeviceLoginResult> {
	const { apiUrl, fetchImpl } = options;
	const sleep = options.sleep ?? defaultSleep;
	const code = await postJson(
		`${apiUrl}/api/auth/device/code`,
		{ client_id: CLI_CLIENT_ID },
		{ fetchImpl },
	);
	const deviceCode = code.body.device_code;
	const userCode = code.body.user_code;
	if (
		!isOk(code.status) ||
		typeof deviceCode !== "string" ||
		typeof userCode !== "string"
	) {
		throw new Error(`Could not start login (HTTP ${code.status}).`);
	}
	const verificationUri = trustedVerificationUri(
		typeof code.body.verification_uri_complete === "string"
			? code.body.verification_uri_complete
			: code.body.verification_uri,
		apiUrl,
		options.consoleUrl,
	);
	options.prompt({
		userCode: terminalSafe(userCode),
		verificationUri: terminalSafe(verificationUri),
	});

	let intervalMs = (Number(code.body.interval) || 5) * 1000;
	const deadline = Date.now() + (Number(code.body.expires_in) || 1800) * 1000;
	let accessToken: string | undefined;
	while (Date.now() < deadline) {
		await sleep(intervalMs);
		const token = await postJson(
			`${apiUrl}/api/auth/device/token`,
			{
				grant_type: DEVICE_GRANT,
				device_code: deviceCode,
				client_id: CLI_CLIENT_ID,
			},
			{ fetchImpl },
		);
		if (isOk(token.status) && typeof token.body.access_token === "string") {
			accessToken = token.body.access_token;
			break;
		}
		const error = token.body.error;
		if (error === "authorization_pending") continue;
		if (error === "slow_down") {
			intervalMs += 5000;
			continue;
		}
		if (error === "access_denied") throw new Error("Login was denied.");
		if (error === "expired_token")
			throw new Error("The login code expired. Run `rouar login` again.");
		throw new Error(
			`Login failed (HTTP ${token.status}${typeof error === "string" ? `, ${terminalSafe(error)}` : ""}).`,
		);
	}
	if (!accessToken)
		throw new Error("The login code expired. Run `rouar login` again.");

	let created: Awaited<ReturnType<typeof postJson>>;
	try {
		created = await postJson(
			`${apiUrl}/api/auth/api-key/create`,
			{ name: CLI_CLIENT_ID },
			{ bearer: accessToken, fetchImpl },
		);
	} finally {
		// API キーに替えたら、セッションは残さない
		await signOut(apiUrl, accessToken, fetchImpl);
	}
	if (!isOk(created.status) || typeof created.body.key !== "string") {
		throw new Error(`Could not create an API key (HTTP ${created.status}).`);
	}
	return {
		apiKey: created.body.key,
		...(typeof created.body.id === "string" ? { keyId: created.body.id } : {}),
	};
}

/**
 * 保存した API キーをサーバーで取り消す。better-auth の api-key の削除を、そのキー自身で呼ぶ。
 * すでに無効か見つからない 401 と 404 は取り消し済みとして扱う
 */
export async function revokeApiKey(
	auth: { apiUrl: string; apiKey: string; keyId?: string },
	fetchImpl?: typeof fetch,
): Promise<"revoked" | "gone" | "unknown-id" | "failed"> {
	if (!auth.keyId) return "unknown-id";
	try {
		const response = await (fetchImpl ?? fetch)(
			`${auth.apiUrl}/api/auth/api-key/delete`,
			{
				method: "POST",
				headers: {
					"content-type": "application/json",
					accept: "application/json",
					authorization: `Bearer ${auth.apiKey}`,
					"x-api-key": auth.apiKey,
				},
				body: JSON.stringify({ keyId: auth.keyId }),
			},
		);
		await response.body?.cancel();
		if (isOk(response.status)) return "revoked";
		if (response.status === 401 || response.status === 404) return "gone";
		return "failed";
	} catch {
		return "failed";
	}
}
