import type { AuthFile } from "./config";
import { terminalSafe } from "./terminal";

export class ApiError extends Error {
	constructor(
		readonly status: number,
		message: string,
	) {
		super(message);
		this.name = "ApiError";
	}
}

async function errorMessage(response: Response): Promise<string> {
	try {
		const body = (await response.json()) as Record<string, unknown>;
		const detail = body.detail ?? body.title ?? body.message ?? body.error;
		if (typeof detail === "string") return terminalSafe(detail);
	} catch {
		// 本文が JSON でなければ、ステータスだけを伝える
	}
	return terminalSafe(`${response.status} ${response.statusText}`);
}

export type ApiGet = <T>(auth: AuthFile, path: string) => Promise<T>;

/** Rouar の API を API キーで呼ぶ */
export async function apiGet<T>(
	auth: AuthFile,
	path: string,
	fetchImpl: typeof fetch = fetch,
): Promise<T> {
	const response = await fetchImpl(`${auth.apiUrl}${path}`, {
		headers: {
			authorization: `Bearer ${auth.apiKey}`,
			accept: "application/json",
		},
	});
	if (!response.ok) {
		throw new ApiError(response.status, await errorMessage(response));
	}
	return (await response.json()) as T;
}

export async function postJson(
	url: string,
	body: unknown,
	options: { bearer?: string; fetchImpl?: typeof fetch } = {},
): Promise<{ status: number; body: Record<string, unknown> }> {
	const response = await (options.fetchImpl ?? fetch)(url, {
		method: "POST",
		headers: {
			"content-type": "application/json",
			accept: "application/json",
			...(options.bearer ? { authorization: `Bearer ${options.bearer}` } : {}),
		},
		body: JSON.stringify(body),
	});
	let parsed: Record<string, unknown> = {};
	try {
		parsed = (await response.json()) as Record<string, unknown>;
	} catch {
		parsed = {};
	}
	return { status: response.status, body: parsed };
}
