import { execFile } from "node:child_process";
import { constants } from "node:fs";
import { lstat, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { promisify } from "node:util";
import { type ApiGet, apiGet } from "./api";
import type { AuthFile } from "./config";
import { writePrivateFile } from "./files";
import { terminalSafe } from "./terminal";

export type Project = {
	id: string;
	name: string;
	slug: string;
	repository?: { fullName?: string } | null;
	productionUrl?: string | null;
};

export const LINK_DIR = ".rouar";
export const LINK_FILE = join(LINK_DIR, "project.json");

/** git の remote の URL から owner/repo を取り出す */
export function repositoryFullName(remoteUrl: string): string | undefined {
	const match = /github\.com[:/]+([^/\s]+)\/([^/\s]+?)(?:\.git)?\/?$/i.exec(
		remoteUrl.trim(),
	);
	return match ? `${match[1]}/${match[2]}` : undefined;
}

export async function gitOriginFullName(
	cwd: string,
): Promise<string | undefined> {
	try {
		const { stdout } = await promisify(execFile)(
			"git",
			["remote", "get-url", "origin"],
			{ cwd },
		);
		return repositoryFullName(stdout);
	} catch {
		return undefined;
	}
}

/**
 * id が完全に一致するものを先に選び、なければ slug で選ぶ。
 * slug が他のプロジェクトの id と重なっても、id の方を選ぶ。複数が一致したら選ばずに止める。
 */
export function findProject(
	projects: readonly Project[],
	selector: string,
): Project {
	for (const field of ["id", "slug"] as const) {
		const matches = projects.filter((p) => p[field] === selector);
		if (matches.length > 1)
			throw new Error(
				`More than one project matches "${terminalSafe(selector)}". Pass the project id instead.`,
			);
		if (matches[0]) return matches[0];
	}
	throw new Error(`No project matches "${terminalSafe(selector)}".`);
}

/** --project の指定か、git の origin に一致するプロジェクトを選ぶ */
export function selectProject(
	projects: readonly Project[],
	selector: string | undefined,
	originFullName: string | undefined,
): Project {
	if (selector) return findProject(projects, selector);
	if (originFullName) {
		const matches = projects.filter(
			(p) =>
				p.repository?.fullName?.toLowerCase() === originFullName.toLowerCase(),
		);
		if (matches.length === 1 && matches[0]) return matches[0];
	}
	const list = projects
		.map(
			(p) =>
				`  ${terminalSafe(p.slug)}  ${terminalSafe(p.repository?.fullName ?? "")}`,
		)
		.join("\n");
	throw new Error(
		`Could not pick a project from the git remote. Pass --project <slug>.${list ? `\n${list}` : ""}`,
	);
}

/** プロジェクトの一覧を API から読む */
export async function listProjects(
	auth: AuthFile,
	get: ApiGet = apiGet,
): Promise<Project[]> {
	const { items } = await get<{ items: Project[] }>(auth, "/api/v1/projects");
	return items;
}

/**
 * --project に渡された id か slug を、プロジェクトの id にする。
 * 指定がなければ、リンクしたプロジェクトの id をそのまま使う。
 */
export async function resolveProjectId(
	auth: AuthFile,
	selector: string | undefined,
	cwd: string,
	get: ApiGet = apiGet,
): Promise<string> {
	if (selector)
		return selectProject(await listProjects(auth, get), selector, undefined).id;
	const linked = await readLink(cwd);
	if (!linked)
		throw new Error(
			"This directory is not linked. Run `rouar link` or pass --project <id or slug>.",
		);
	return linked;
}

export async function readLink(cwd: string): Promise<string | undefined> {
	try {
		const parsed = JSON.parse(await readFile(join(cwd, LINK_FILE), "utf8")) as {
			projectId?: unknown;
		};
		return typeof parsed.projectId === "string" ? parsed.projectId : undefined;
	} catch {
		return undefined;
	}
}

/** パスがシンボリックリンクなら止める。リンクの先にある別のファイルを書き換えないため */
async function refuseSymlink(path: string): Promise<void> {
	try {
		if ((await lstat(path)).isSymbolicLink()) {
			throw new Error(
				`${path} is a symbolic link. rouar does not write through symbolic links; replace it with a regular file or directory.`,
			);
		}
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code === "ENOENT") return;
		throw error;
	}
}

/** .gitignore を書くときもリンクをたどらない。O_NOFOLLOW がない環境では lstat の確認だけになる */
const NO_FOLLOW_WRITE =
	constants.O_WRONLY |
	constants.O_CREAT |
	constants.O_TRUNC |
	(constants.O_NOFOLLOW ?? 0);

/** .rouar/project.json を書き、.gitignore に .rouar/ がなければ足す。rouar sdk add が直した .rouar/* の形も無視の指定とみなす */
export async function writeLink(
	cwd: string,
	projectId: string,
): Promise<{ gitignoreUpdated: boolean }> {
	const gitignorePath = join(cwd, ".gitignore");
	for (const path of [
		join(cwd, LINK_DIR),
		join(cwd, LINK_FILE),
		gitignorePath,
	]) {
		await refuseSymlink(path);
	}
	await writePrivateFile(
		join(cwd, LINK_FILE),
		`${JSON.stringify({ projectId }, null, 2)}\n`,
	);
	let gitignore = "";
	try {
		gitignore = await readFile(gitignorePath, "utf8");
	} catch {
		gitignore = "";
	}
	const ignored = gitignore
		.split(/\r?\n/)
		.some((line) =>
			[
				"/.rouar",
				"/.rouar/",
				".rouar",
				".rouar/",
				"/.rouar/*",
				".rouar/*",
			].includes(line.trim()),
		);
	if (ignored) return { gitignoreUpdated: false };
	const prefix = gitignore === "" || gitignore.endsWith("\n") ? "" : "\n";
	await writeFile(gitignorePath, `${gitignore}${prefix}.rouar/\n`, {
		flag: NO_FOLLOW_WRITE,
	});
	return { gitignoreUpdated: true };
}
