import { chmod, mkdir, readFile, rm } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";
import { writePrivateFile } from "./files";

export const DEFAULT_API_URL = "https://api.rouar.com";
/** デバイスの承認の画面を出すコンソール。ROUAR_CONSOLE_URL で変えられる */
export const DEFAULT_CONSOLE_URL = "https://console.rouar.com";

export type AuthFile = {
	apiUrl: string;
	apiKey: string;
	/** ログアウトのときに API キーを取り消すための id */
	keyId?: string;
};

export function configDir(env: NodeJS.ProcessEnv = process.env): string {
	const base = env.XDG_CONFIG_HOME || join(homedir(), ".config");
	return join(base, "rouar");
}

export function authFilePath(env: NodeJS.ProcessEnv = process.env): string {
	return join(configDir(env), "auth.json");
}

function normalizeUrl(name: string, url: string): string {
	const parsed = new URL(url);
	if (
		parsed.protocol !== "https:" &&
		!(parsed.protocol === "http:" && isLoopback(parsed.hostname))
	) {
		throw new Error(`${name} must use https: ${url}`);
	}
	return parsed.href.replace(/\/+$/, "");
}

export function normalizeApiUrl(url: string): string {
	return normalizeUrl("ROUAR_API_URL", url);
}

export function resolveConsoleUrl(
	env: NodeJS.ProcessEnv = process.env,
): string {
	return normalizeUrl(
		"ROUAR_CONSOLE_URL",
		env.ROUAR_CONSOLE_URL || DEFAULT_CONSOLE_URL,
	);
}

function isLoopback(hostname: string): boolean {
	return (
		hostname === "localhost" || hostname === "127.0.0.1" || hostname === "[::1]"
	);
}

export async function readAuth(
	env: NodeJS.ProcessEnv = process.env,
): Promise<AuthFile | undefined> {
	try {
		const parsed = JSON.parse(
			await readFile(authFilePath(env), "utf8"),
		) as unknown;
		if (
			typeof parsed === "object" &&
			parsed !== null &&
			typeof (parsed as AuthFile).apiUrl === "string" &&
			typeof (parsed as AuthFile).apiKey === "string"
		) {
			const { apiUrl, apiKey, keyId } = parsed as AuthFile;
			return typeof keyId === "string"
				? { apiUrl, apiKey, keyId }
				: { apiUrl, apiKey };
		}
		return undefined;
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
		throw error;
	}
}

/** API キーを 0600 で保存する。ディレクトリは 0700 で作る */
export async function saveAuth(
	auth: AuthFile,
	env: NodeJS.ProcessEnv = process.env,
): Promise<string> {
	const path = authFilePath(env);
	await mkdir(configDir(env), { recursive: true, mode: 0o700 });
	await chmod(configDir(env), 0o700);
	await writePrivateFile(path, `${JSON.stringify(auth, null, 2)}\n`);
	return path;
}

export async function removeAuth(
	env: NodeJS.ProcessEnv = process.env,
): Promise<boolean> {
	const existing = await readAuth(env).catch(() => undefined);
	await rm(authFilePath(env), { force: true });
	return existing !== undefined;
}

/** 使う API の URL を決める。ROUAR_API_URL、保存した URL、既定の URL の順に見る */
export function resolveApiUrl(env: NodeJS.ProcessEnv, auth?: AuthFile): string {
	return normalizeApiUrl(env.ROUAR_API_URL || auth?.apiUrl || DEFAULT_API_URL);
}

/** ログインしていないことを表す。CLI は rouar login を案内して終わる */
export class NotLoggedInError extends Error {
	override readonly name = "NotLoggedInError";
}

/** 保存した API キーを返す。別の API にログインしていたら使わない */
export async function requireAuth(
	env: NodeJS.ProcessEnv = process.env,
): Promise<AuthFile> {
	const auth = await readAuth(env);
	const apiUrl = resolveApiUrl(env, auth);
	if (!auth || normalizeApiUrl(auth.apiUrl) !== apiUrl) {
		throw new NotLoggedInError(
			`Not logged in to ${apiUrl}. Run \`rouar login\` first.`,
		);
	}
	return { apiUrl, apiKey: auth.apiKey };
}
