#!/usr/bin/env node
import { resolve } from "node:path";
import { defineCommand, runMain } from "citty";
import { apiGet } from "./cli/api";
import {
	DEFAULT_API_URL,
	NotLoggedInError,
	normalizeApiUrl,
	readAuth,
	removeAuth,
	requireAuth,
	resolveConsoleUrl,
	saveAuth,
} from "./cli/config";
import {
	EnvFileConflictError,
	type EnvVariable,
	formatEnvFile,
	PULLABLE_ENVIRONMENTS,
	writeEnvFile,
} from "./cli/env-pull";
import {
	gitOriginFullName,
	LINK_FILE,
	listProjects,
	resolveProjectId,
	selectProject,
	writeLink,
} from "./cli/link";
import { deviceLogin, revokeApiKey } from "./cli/login";
import { prepare } from "./cli/prepare";
import {
	findRepositoryRoot,
	installCommand,
	SdkAddError,
	SdkAuthError,
	sdkAdd,
} from "./cli/sdk-add";
import { terminalSafe } from "./cli/terminal";

const login = defineCommand({
	meta: { name: "login", description: "Sign in to rouar and store an API key" },
	async run() {
		const apiUrl = normalizeApiUrl(
			process.env.ROUAR_API_URL || DEFAULT_API_URL,
		);
		const { apiKey, keyId } = await deviceLogin({
			apiUrl,
			consoleUrl: resolveConsoleUrl(),
			prompt: ({ userCode, verificationUri }) => {
				console.log(
					`Open ${verificationUri} and confirm the code ${userCode}.`,
				);
				console.log("Waiting for approval...");
			},
		});
		const path = await saveAuth({
			apiUrl,
			apiKey,
			...(keyId ? { keyId } : {}),
		});
		console.log(`Logged in to ${apiUrl}. Saved the API key to ${path}.`);
	},
});

const logout = defineCommand({
	meta: {
		name: "logout",
		description: "Revoke and remove the stored API key",
	},
	async run() {
		const auth = await readAuth().catch(() => undefined);
		if (auth) {
			// 保存した URL も https に限る。読めなければ取り消さずに消す
			let apiUrl: string | undefined;
			try {
				apiUrl = normalizeApiUrl(auth.apiUrl);
			} catch {
				apiUrl = undefined;
			}
			const result = apiUrl
				? await revokeApiKey({ ...auth, apiUrl })
				: "failed";
			if (result === "unknown-id" || result === "failed")
				console.warn(
					"Could not revoke the API key on the server. Revoke it in the rouar console.",
				);
		}
		const removed = await removeAuth();
		console.log(removed ? "Logged out." : "Not logged in.");
	},
});

const link = defineCommand({
	meta: { name: "link", description: "Link this directory to a rouar project" },
	args: {
		project: { type: "string", description: "Project id or slug" },
	},
	async run({ args }) {
		const cwd = process.cwd();
		const auth = await requireAuth();
		const project = selectProject(
			await listProjects(auth),
			args.project,
			await gitOriginFullName(cwd),
		);
		const { gitignoreUpdated } = await writeLink(cwd, project.id);
		console.log(
			`Linked to ${terminalSafe(project.name)} (${terminalSafe(project.slug)}). Wrote ${LINK_FILE}.`,
		);
		if (gitignoreUpdated) console.log("Added .rouar/ to .gitignore.");
	},
});

const envPull = defineCommand({
	meta: {
		name: "pull",
		description: "Write the project's environment variables to a .env file",
	},
	args: {
		environment: {
			type: "enum",
			options: [...PULLABLE_ENVIRONMENTS],
			default: "development",
			description:
				"Environment to read. Only development can be pulled; preview and production values stay on rouar",
		},
		file: { type: "string", default: ".env", description: "File to write" },
		project: {
			type: "string",
			description: "Project id or slug. Defaults to the linked project",
		},
		yes: {
			type: "boolean",
			default: false,
			description: "Overwrite the file if it differs",
		},
	},
	async run({ args }) {
		const cwd = process.cwd();
		const auth = await requireAuth();
		const projectId = await resolveProjectId(auth, args.project, cwd);
		const query = new URLSearchParams({ environment: args.environment });
		const { variables } = await apiGet<{ variables: EnvVariable[] }>(
			auth,
			`/api/v1/projects/${encodeURIComponent(projectId)}/env?${query}`,
		);
		const { content, skipped } = formatEnvFile(variables);
		const path = resolve(cwd, args.file);
		try {
			const result = await writeEnvFile(path, content, args.yes);
			console.log(
				`${result === "unchanged" ? "Already up to date" : result === "created" ? "Created" : "Updated"} ${args.file} (${variables.length - skipped.length} variables).`,
			);
		} catch (error) {
			if (error instanceof EnvFileConflictError) {
				console.error(error.message);
				process.exitCode = 1;
				return;
			}
			throw error;
		}
		for (const key of skipped)
			console.warn(
				`Skipped ${terminalSafe(key)}: it cannot be written to a .env file.`,
			);
	},
});

const env = defineCommand({
	meta: { name: "env", description: "Manage environment variables" },
	subCommands: { pull: envPull },
});

const prepareCommand = defineCommand({
	meta: {
		name: "prepare",
		description: "Prepare a Flue project for a rouar build",
	},
	args: {
		cwd: { type: "string", default: ".", description: "Project root" },
	},
	async run({ args }) {
		const result = await prepare(resolve(process.cwd(), args.cwd));
		for (const action of result.actions)
			console.log(`rouar prepare: ${action}`);
		for (const warning of result.warnings)
			console.warn(`rouar prepare: warning: ${warning}`);
	},
});

const sdkAddCommand = defineCommand({
	meta: {
		name: "add",
		description:
			"Download the @rouar/sdk tarball into .rouar/ and add it to your agent and frontend packages",
	},
	args: {
		cwd: {
			type: "string",
			default: ".",
			description: "A directory inside the repository",
		},
	},
	async run({ args }) {
		try {
			const auth = await requireAuth();
			const root = await findRepositoryRoot(resolve(process.cwd(), args.cwd));
			const result = await sdkAdd(auth, root);
			console.log(
				`${result.downloaded ? "Downloaded" : "Already have"} @rouar/sdk ${terminalSafe(result.release.version)} at ${terminalSafe(result.tarballPath)}.`,
			);
			for (const name of result.removed)
				console.log(`Removed the old ${terminalSafe(name)}.`);
			for (const { dir, spec, change } of result.packages)
				console.log(
					`${dir}/package.json: ${change === "unchanged" ? "already uses" : change === "added" ? "added" : "updated to"} "@rouar/sdk": "${terminalSafe(spec)}"`,
				);
			if (result.gitignoreUpdated)
				console.log(
					"Updated .gitignore so the tarball in .rouar/ can be committed.",
				);
			console.log(
				`Run \`${installCommand(result.packageManager)}\`, then commit ${terminalSafe(result.tarballPath)} with your package.json changes so collaborators can install without an API key.`,
			);
		} catch (error) {
			if (
				error instanceof NotLoggedInError ||
				error instanceof SdkAuthError ||
				error instanceof SdkAddError
			) {
				console.error(error.message);
				process.exitCode = 1;
				return;
			}
			throw error;
		}
	},
});

const sdk = defineCommand({
	meta: { name: "sdk", description: "Manage the @rouar/sdk package" },
	subCommands: { add: sdkAddCommand },
});

const main = defineCommand({
	meta: { name: "rouar", description: "Deploy Flue agents on rouar" },
	subCommands: { login, logout, link, env, sdk, prepare: prepareCommand },
});

await runMain(main);
