import { access, writeFile } from "node:fs/promises";
import { join, relative } from "node:path";

const ENTRY_EXTENSIONS = ["ts", "mts", "js", "mjs"] as const;

export const DB_SHIM = `// Created by rouar prepare. Stores Flue sessions and submissions in the rouar Postgres database.
export { default } from "@rouar/sdk/db";
`;

async function exists(path: string): Promise<boolean> {
	try {
		await access(path);
		return true;
	} catch {
		return false;
	}
}

/** Flue と同じ順で、ソースのルートを決める。.flue、src、プロジェクトのルートの順に見る */
export async function resolveFlueSourceRoot(root: string): Promise<string> {
	for (const candidate of [join(root, ".flue"), join(root, "src")]) {
		if (await exists(candidate)) return candidate;
	}
	return root;
}

async function findEntry(
	dir: string,
	name: string,
): Promise<string | undefined> {
	for (const extension of ENTRY_EXTENSIONS) {
		const path = join(dir, `${name}.${extension}`);
		if (await exists(path)) return path;
	}
	return undefined;
}

export type PrepareResult = {
	sourceRoot: string;
	actions: string[];
	warnings: string[];
};

/**
 * ビルドの前に呼ぶ。db.* がなければ、Rouar の Postgres を使う db.ts を書く。
 * 何度呼んでも結果は同じになる。
 */
export async function prepare(root: string): Promise<PrepareResult> {
	const sourceRoot = await resolveFlueSourceRoot(root);
	const shown = relative(root, sourceRoot) || ".";
	const actions: string[] = [`source root: ${shown}`];
	const warnings: string[] = [];
	if (!(await findEntry(sourceRoot, "app"))) {
		warnings.push(`no app.{ts,mts,js,mjs} in ${shown}; Flue needs one`);
	}
	const db = await findEntry(sourceRoot, "db");
	if (db) {
		actions.push(`kept ${relative(root, db)}`);
	} else {
		const path = join(sourceRoot, "db.ts");
		await writeFile(path, DB_SHIM, { flag: "wx" });
		actions.push(`wrote ${relative(root, path)}`);
	}
	return { sourceRoot, actions, warnings };
}
