import { createHash, randomBytes } from "node:crypto";
import {
	lstat,
	mkdir,
	readdir,
	readFile,
	rename,
	rm,
	writeFile,
} from "node:fs/promises";
import { isAbsolute, join, posix, relative, resolve, sep } from "node:path";
import fg from "fast-glob";
import { ApiError, apiGet } from "./api";
import type { AuthFile } from "./config";
import { terminalSafe } from "./terminal";

/** tarball を置く、リポジトリの直下のディレクトリ */
export const SDK_DIR = ".rouar";
/** API が返す tarball の名前の形。パスの区切りや .. を含む名前は受け取らない */
const FILE_NAME = /^rouar-sdk-[0-9A-Za-z][0-9A-Za-z.-]*\.tgz$/;
/** 受け取る tarball の大きさの上限 */
export const MAX_SDK_BYTES = 64 * 1024 * 1024;
/** .gitignore で .rouar/ を無視していても、tarball はコミットできるようにする */
export const GITIGNORE_SDK_EXCEPTION = "!/.rouar/rouar-sdk-*.tgz";

export type SdkRelease = {
	version: string;
	fileName: string;
	url: string;
	integrity: string;
	size: number;
};

export type PackageManager = "pnpm" | "npm" | "yarn" | "bun";

export class SdkAddError extends Error {
	override readonly name = "SdkAddError";
}

/** API キーが通らなかったことを表す。ログインし直してもらう */
export class SdkAuthError extends Error {
	override readonly name = "SdkAuthError";
}

function sha512(bytes: Uint8Array): string {
	return `sha512-${createHash("sha512").update(bytes).digest("base64")}`;
}

/** API の応答を確かめる。名前と版がそろわないもの、大きすぎるものは受け取らない */
export function parseRelease(body: unknown): SdkRelease {
	const release = body as Partial<SdkRelease> | null;
	if (
		typeof release !== "object" ||
		release === null ||
		typeof release.version !== "string" ||
		typeof release.fileName !== "string" ||
		typeof release.integrity !== "string" ||
		typeof release.size !== "number" ||
		!FILE_NAME.test(release.fileName) ||
		release.fileName !== `rouar-sdk-${release.version}.tgz` ||
		!release.integrity.startsWith("sha512-") ||
		!Number.isInteger(release.size) ||
		release.size <= 0 ||
		release.size > MAX_SDK_BYTES
	) {
		throw new SdkAddError("The API returned an unexpected SDK release.");
	}
	return {
		version: release.version,
		fileName: release.fileName,
		url: `/api/v1/sdk/${release.fileName}`,
		integrity: release.integrity,
		size: release.size,
	};
}

/**
 * 中身が API の示した値と合うかを確かめる。
 * 版の末尾の `sha<12 桁>` は中身の SHA-256 の先頭なので、それも比べる
 */
export function verifyTarball(release: SdkRelease, bytes: Uint8Array): void {
	if (
		bytes.byteLength !== release.size ||
		sha512(bytes) !== release.integrity
	) {
		throw new SdkAddError(
			`The downloaded ${release.fileName} does not match its integrity. Run the command again.`,
		);
	}
	const suffix = /sha([0-9a-f]{12})$/.exec(release.version)?.[1];
	const sha256 = createHash("sha256").update(bytes).digest("hex");
	if (suffix !== undefined && !sha256.startsWith(suffix)) {
		throw new SdkAddError(
			`The downloaded ${release.fileName} does not match its version.`,
		);
	}
}

function authFailure(error: unknown): never {
	if (
		error instanceof ApiError &&
		(error.status === 401 || error.status === 403)
	)
		throw new SdkAuthError(
			"The stored API key was rejected. Run `rouar login` again.",
		);
	throw error;
}

/** 最新の版を API に聞き、tarball を取って確かめる */
export async function downloadLatestSdk(
	auth: AuthFile,
	options: {
		fetchImpl?: typeof fetch;
		/** 手元にある tarball。中身が合えば取り直さない */
		existing?: (release: SdkRelease) => Promise<Uint8Array | undefined>;
	} = {},
): Promise<{ release: SdkRelease; bytes: Uint8Array; downloaded: boolean }> {
	const fetchImpl = options.fetchImpl ?? fetch;
	const release = parseRelease(
		await apiGet<unknown>(auth, "/api/v1/sdk/latest", fetchImpl).catch(
			authFailure,
		),
	);
	const cached = await options.existing?.(release);
	if (cached) {
		try {
			verifyTarball(release, cached);
			return { release, bytes: cached, downloaded: false };
		} catch {
			// 壊れた手元のファイルは取り直して置き換える
		}
	}
	// URL は応答をそのまま使わず、確かめた名前から組み立てる。別のホストへ API キーを送らないため
	const response = await fetchImpl(`${auth.apiUrl}${release.url}`, {
		headers: {
			authorization: `Bearer ${auth.apiKey}`,
			accept: "application/gzip",
		},
	});
	if (!response.ok) {
		authFailure(
			new ApiError(
				response.status,
				terminalSafe(`${response.status} ${response.statusText}`),
			),
		);
	}
	const declared = Number(response.headers.get("content-length"));
	if (Number.isFinite(declared) && declared > MAX_SDK_BYTES) {
		throw new SdkAddError("The SDK tarball is too large.");
	}
	const bytes = new Uint8Array(await response.arrayBuffer());
	verifyTarball(release, bytes);
	return { release, bytes, downloaded: true };
}

/** パスがシンボリックリンクなら止める。リンクの先にある別のファイルを書き換えないため */
async function refuseSymlink(path: string): Promise<boolean> {
	try {
		if ((await lstat(path)).isSymbolicLink()) {
			throw new SdkAddError(
				`${path} is a symbolic link. rouar does not write through symbolic links; replace it with a regular file or directory.`,
			);
		}
		return true;
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
		throw error;
	}
}

/** 別名で書いてから置き換える。コミットするファイルなので、ふつうの権限で書く */
async function writeAtomic(path: string, content: string | Uint8Array) {
	const temporary = join(
		resolve(path, ".."),
		`.${randomBytes(6).toString("hex")}.tmp`,
	);
	try {
		await writeFile(temporary, content, { mode: 0o644, flag: "wx" });
		await rename(temporary, path);
	} catch (error) {
		await rm(temporary, { force: true });
		throw error;
	}
}

/** 手元の tarball を読む。なければ undefined */
export async function readLocalTarball(
	root: string,
	fileName: string,
): Promise<Uint8Array | undefined> {
	const path = join(root, SDK_DIR, fileName);
	try {
		if (!(await lstat(path)).isFile()) return undefined;
		return new Uint8Array(await readFile(path));
	} catch {
		return undefined;
	}
}

/** tarball を .rouar/ に置き、ほかの版の tarball を消す。消した名前を返す */
export async function storeTarball(
	root: string,
	release: SdkRelease,
	bytes: Uint8Array,
): Promise<string[]> {
	const dir = join(root, SDK_DIR);
	await refuseSymlink(dir);
	await mkdir(dir, { recursive: true });
	const path = join(dir, release.fileName);
	await refuseSymlink(path);
	await writeAtomic(path, bytes);
	const removed: string[] = [];
	for (const entry of await readdir(dir)) {
		if (entry !== release.fileName && FILE_NAME.test(entry)) {
			await rm(join(dir, entry), { force: true });
			removed.push(entry);
		}
	}
	return removed;
}

type PackageJson = {
	packageManager?: unknown;
	workspaces?: unknown;
	dependencies?: Record<string, string>;
	devDependencies?: Record<string, string>;
	optionalDependencies?: Record<string, string>;
	peerDependencies?: Record<string, string>;
};

async function readPackageJson(dir: string): Promise<PackageJson | undefined> {
	const path = join(dir, "package.json");
	try {
		const stats = await lstat(path);
		if (!stats.isFile()) return undefined;
	} catch {
		return undefined;
	}
	try {
		const parsed = JSON.parse(await readFile(path, "utf8")) as unknown;
		return typeof parsed === "object" &&
			parsed !== null &&
			!Array.isArray(parsed)
			? (parsed as PackageJson)
			: undefined;
	} catch {
		throw new SdkAddError(`${path} is not valid JSON.`);
	}
}

async function exists(path: string): Promise<boolean> {
	try {
		await lstat(path);
		return true;
	} catch {
		return false;
	}
}

/** package.json の packageManager を先に見て、なければロックファイルで決める。どれもなければ npm */
export async function detectPackageManager(
	root: string,
): Promise<PackageManager> {
	const manifest = await readPackageJson(root);
	if (typeof manifest?.packageManager === "string") {
		const name = manifest.packageManager.split("@")[0];
		if (name === "pnpm" || name === "npm" || name === "yarn" || name === "bun")
			return name;
	}
	if (await exists(join(root, "pnpm-lock.yaml"))) return "pnpm";
	if (await exists(join(root, "pnpm-workspace.yaml"))) return "pnpm";
	if (await exists(join(root, "yarn.lock"))) return "yarn";
	if (
		(await exists(join(root, "bun.lock"))) ||
		(await exists(join(root, "bun.lockb")))
	)
		return "bun";
	return "npm";
}

/** pnpm-workspace.yaml の packages の一覧を読む。ブロックの形と [a, b] の形だけを扱う */
export function parsePnpmWorkspace(content: string): string[] {
	const unquote = (value: string) =>
		value.trim().replace(/^(['"])(.*)\1$/, "$2");
	const lines = content.split(/\r?\n/);
	const start = lines.findIndex((line) => /^packages\s*:/.test(line));
	if (start === -1) return [];
	const inline = /^packages\s*:\s*\[(.*)\]\s*$/.exec(lines[start] ?? "");
	if (inline?.[1] !== undefined)
		return inline[1]
			.split(",")
			.map(unquote)
			.filter((item) => item !== "");
	const patterns: string[] = [];
	for (const line of lines.slice(start + 1)) {
		if (/^\s*(#.*)?$/.test(line)) continue;
		const item = /^\s+-\s*(.+?)\s*(?:#.*)?$/.exec(line);
		if (!item?.[1]) break;
		patterns.push(unquote(item[1]));
	}
	return patterns;
}

async function workspacePatterns(root: string): Promise<string[]> {
	try {
		const path = join(root, "pnpm-workspace.yaml");
		if ((await lstat(path)).isFile())
			return parsePnpmWorkspace(await readFile(path, "utf8"));
	} catch {
		// pnpm のワークスペースでなければ package.json を見る
	}
	const workspaces = (await readPackageJson(root))?.workspaces;
	const list = Array.isArray(workspaces)
		? workspaces
		: typeof workspaces === "object" &&
				workspaces !== null &&
				Array.isArray((workspaces as { packages?: unknown }).packages)
			? (workspaces as { packages: unknown[] }).packages
			: [];
	return list.filter((item): item is string => typeof item === "string");
}

/** ワークスペースのパッケージのディレクトリを、リポジトリの直下からの POSIX の相対パスで返す。直下は "." */
export async function listWorkspacePackages(root: string): Promise<string[]> {
	const patterns = await workspacePatterns(root);
	const include: string[] = [];
	const ignore = ["**/node_modules/**"];
	for (const raw of patterns) {
		const negated = raw.startsWith("!");
		const pattern = (negated ? raw.slice(1) : raw)
			.replace(/^\.\//, "")
			.replace(/\/+$/, "");
		if (pattern === "" || pattern.split("/").includes("..")) continue;
		(negated ? ignore : include).push(`${pattern}/package.json`);
	}
	const found = include.length
		? await fg(include, {
				cwd: root,
				ignore,
				onlyFiles: true,
				followSymbolicLinks: false,
			})
		: [];
	const dirs = new Set(["."]);
	for (const file of found) dirs.add(posix.dirname(file));
	return [...dirs].sort();
}

function allDependencies(manifest: PackageJson): Record<string, string> {
	return {
		...manifest.peerDependencies,
		...manifest.optionalDependencies,
		...manifest.devDependencies,
		...manifest.dependencies,
	};
}

function isAgent(deps: Record<string, string>): boolean {
	return "@flue/vite" in deps;
}

/** docs/frontend.md の自動の見つけ方と同じ見分け方。next は受け付けないので選ばない */
function isFrontend(deps: Record<string, string>): boolean {
	if (isAgent(deps) || "next" in deps) return false;
	if ("nuxt" in deps || "@sveltejs/kit" in deps) return true;
	return "vite" in deps && ("vue" in deps || "react" in deps);
}

type RouarConfig = {
	agentRoot?: string;
	frontendRoot?: string;
	frontendDisabled: boolean;
};

/** リポジトリの外を指すパスは受け付けない */
function insideRoot(root: string, path: string, name: string): string {
	const relativePath = relative(root, resolve(root, path));
	if (
		isAbsolute(path) ||
		relativePath.startsWith("..") ||
		isAbsolute(relativePath)
	) {
		throw new SdkAddError(
			`${name} in rouar.json must be inside the repository.`,
		);
	}
	return relativePath.split(sep).join("/") || ".";
}

async function readRouarConfig(root: string): Promise<RouarConfig> {
	const path = join(root, "rouar.json");
	let content: string;
	try {
		if (!(await lstat(path)).isFile()) return { frontendDisabled: false };
		content = await readFile(path, "utf8");
	} catch {
		return { frontendDisabled: false };
	}
	let parsed: { agent?: { root?: unknown }; frontend?: unknown };
	try {
		parsed = JSON.parse(content) as typeof parsed;
	} catch {
		throw new SdkAddError("rouar.json is not valid JSON.");
	}
	const frontend = parsed.frontend as { root?: unknown } | false | undefined;
	return {
		...(typeof parsed.agent?.root === "string"
			? { agentRoot: insideRoot(root, parsed.agent.root, "agent.root") }
			: {}),
		...(typeof frontend === "object" &&
		frontend !== null &&
		typeof frontend.root === "string"
			? { frontendRoot: insideRoot(root, frontend.root, "frontend.root") }
			: {}),
		frontendDisabled: frontend === false,
	};
}

/**
 * @rouar/sdk を足すパッケージを選ぶ。rouar.json で決めた場所を先に使い、なければ自動で見つける。
 * すでに @rouar/sdk に依存するパッケージも、版をそろえるために選ぶ
 */
export async function findTargetPackages(root: string): Promise<string[]> {
	const config = await readRouarConfig(root);
	const targets = new Set<string>();
	for (const dir of [config.agentRoot, config.frontendRoot]) {
		if (dir === undefined) continue;
		if (!(await readPackageJson(join(root, dir))))
			throw new SdkAddError(
				`${dir}/package.json from rouar.json was not found.`,
			);
		targets.add(dir);
	}
	for (const dir of await listWorkspacePackages(root)) {
		const manifest = await readPackageJson(join(root, dir));
		if (!manifest) continue;
		const deps = allDependencies(manifest);
		if ("@rouar/sdk" in deps) targets.add(dir);
		if (config.agentRoot === undefined && isAgent(deps)) targets.add(dir);
		if (
			config.frontendRoot === undefined &&
			!config.frontendDisabled &&
			isFrontend(deps)
		)
			targets.add(dir);
	}
	if (targets.size === 0) {
		throw new SdkAddError(
			"No agent package was found. Add @flue/vite to your agent's package.json or set agent.root in rouar.json.",
		);
	}
	return [...targets].sort();
}

/** パッケージから見た tarball の `file:` の指定 */
export function fileSpec(root: string, packageDir: string, fileName: string) {
	const path = relative(join(root, packageDir), join(root, SDK_DIR, fileName))
		.split(sep)
		.join("/");
	return `file:${path}`;
}

function detectIndent(content: string): string | number {
	return /^([ \t]+)"/m.exec(content)?.[1] ?? 2;
}

const DEPENDENCY_FIELDS = [
	"dependencies",
	"devDependencies",
	"optionalDependencies",
] as const;

export type DependencyChange = "added" | "updated" | "unchanged";

/**
 * package.json に `"@rouar/sdk": "file:..."` を書く。すでにある欄はそのまま使い、
 * なければ dependencies に足す。字下げと末尾の改行は元のファイルに合わせる
 */
export async function writeSdkDependency(
	root: string,
	packageDir: string,
	spec: string,
): Promise<DependencyChange> {
	const path = join(root, packageDir, "package.json");
	await refuseSymlink(path);
	const content = await readFile(path, "utf8");
	let manifest: Record<string, unknown>;
	try {
		manifest = JSON.parse(content) as Record<string, unknown>;
	} catch {
		throw new SdkAddError(`${path} is not valid JSON.`);
	}
	const field =
		DEPENDENCY_FIELDS.find((name) => {
			const deps = manifest[name];
			return typeof deps === "object" && deps !== null && "@rouar/sdk" in deps;
		}) ?? "dependencies";
	const deps = { ...((manifest[field] as Record<string, string>) ?? {}) };
	const previous = deps["@rouar/sdk"];
	if (previous === spec) return "unchanged";
	deps["@rouar/sdk"] = spec;
	// 新しく足すときは、パッケージマネージャーと同じく名前の順に並べる
	manifest[field] =
		previous === undefined
			? Object.fromEntries(
					Object.entries(deps).sort(([a], [b]) => a.localeCompare(b)),
				)
			: deps;
	const newline = content.includes("\r\n") ? "\r\n" : "\n";
	let output = JSON.stringify(manifest, null, detectIndent(content));
	if (newline === "\r\n") output = output.replace(/\n/g, "\r\n");
	if (/\r?\n$/.test(content)) output += newline;
	await writeAtomic(path, output);
	return previous === undefined ? "added" : "updated";
}

/**
 * .gitignore が .rouar/ を丸ごと無視していたら、中身だけを無視する形に直し、tarball を例外にする。
 * git はディレクトリを無視すると、その中のファイルを例外にできないため
 */
export async function allowTarballInGitignore(root: string): Promise<boolean> {
	const path = join(root, ".gitignore");
	if (!(await refuseSymlink(path))) return false;
	const content = await readFile(path, "utf8");
	const lines = content.split(/\r?\n/);
	let ignoresDir = false;
	const next = lines.map((line) => {
		const trimmed = line.trim();
		if ([".rouar", ".rouar/", "/.rouar", "/.rouar/"].includes(trimmed)) {
			ignoresDir = true;
			return "/.rouar/*";
		}
		if ([".rouar/*", "/.rouar/*"].includes(trimmed)) ignoresDir = true;
		return line;
	});
	if (!ignoresDir) return false;
	if (!next.some((line) => line.trim() === GITIGNORE_SDK_EXCEPTION)) {
		const index = next.findIndex((line) =>
			[".rouar/*", "/.rouar/*"].includes(line.trim()),
		);
		next.splice(index + 1, 0, GITIGNORE_SDK_EXCEPTION);
	}
	const output = next.join(content.includes("\r\n") ? "\r\n" : "\n");
	if (output === content) return false;
	await writeAtomic(path, output);
	return true;
}

export function installCommand(packageManager: PackageManager): string {
	return `${packageManager} install`;
}

/** 親へたどって .git のあるディレクトリを探す。なければ start をそのまま使う */
export async function findRepositoryRoot(start: string): Promise<string> {
	let dir = resolve(start);
	for (;;) {
		if (await exists(join(dir, ".git"))) return dir;
		const parent = resolve(dir, "..");
		if (parent === dir) return resolve(start);
		dir = parent;
	}
}

export type SdkAddResult = {
	release: SdkRelease;
	downloaded: boolean;
	tarballPath: string;
	removed: string[];
	packages: { dir: string; spec: string; change: DependencyChange }[];
	gitignoreUpdated: boolean;
	packageManager: PackageManager;
};

/** rouar sdk add の本体。tarball を取り、.rouar/ に置き、各パッケージに file: の依存を書く */
export async function sdkAdd(
	auth: AuthFile,
	root: string,
	options: { fetchImpl?: typeof fetch } = {},
): Promise<SdkAddResult> {
	// 書き込む先を先に決め、パッケージが見つからなければ取りに行かない
	const dirs = await findTargetPackages(root);
	const { release, bytes, downloaded } = await downloadLatestSdk(auth, {
		...(options.fetchImpl ? { fetchImpl: options.fetchImpl } : {}),
		existing: (r) => readLocalTarball(root, r.fileName),
	});
	const removed = await storeTarball(root, release, bytes);
	const packages = [];
	for (const dir of dirs) {
		const spec = fileSpec(root, dir, release.fileName);
		packages.push({
			dir,
			spec,
			change: await writeSdkDependency(root, dir, spec),
		});
	}
	return {
		release,
		downloaded,
		tarballPath: posix.join(SDK_DIR, release.fileName),
		removed,
		packages,
		gitignoreUpdated: await allowTarballInGitignore(root),
		packageManager: await detectPackageManager(root),
	};
}
