import { readFile } from "node:fs/promises";
import { writePrivateFile } from "./files";

/**
 * API が env pull に値を返すのは development だけ。preview と production は 403 になる。
 * 実行時の秘密を手元に出さないための決まりなので、CLI でも受け付けない。
 */
export const PULLABLE_ENVIRONMENTS = ["development"] as const;

export type EnvVariable = { key: string; value: string; source?: string };

const ENV_KEY = /^[A-Za-z_][A-Za-z0-9_]*$/;

/**
 * dotenv の 1 行の値にする。dotenv は二重引用符の中の改行のエスケープしか解かないので、
 * 値に合わせて引用符を選ぶ。どの形でも読み戻せない値は undefined を返す。
 */
export function quoteEnvValue(value: string): string | undefined {
	if (value.includes("\r")) return undefined;
	const multiline = value.includes("\n");
	if (!multiline && !value.includes("'")) return `'${value}'`;
	if (!value.includes('"') && !value.includes("\\")) {
		return `"${value.replace(/\n/g, "\\n")}"`;
	}
	if (!multiline && !value.includes("`")) return `\`${value}\``;
	return undefined;
}

export function formatEnvFile(variables: readonly EnvVariable[]): {
	content: string;
	skipped: string[];
} {
	const skipped: string[] = [];
	const lines = ["# Created by `rouar env pull`. Do not commit this file."];
	const sorted = [...variables].sort((a, b) => a.key.localeCompare(b.key));
	for (const { key, value } of sorted) {
		if (!ENV_KEY.test(key)) {
			skipped.push(key);
			continue;
		}
		const quoted = quoteEnvValue(value);
		if (quoted === undefined) {
			skipped.push(key);
			continue;
		}
		lines.push(`${key}=${quoted}`);
	}
	return { content: `${lines.join("\n")}\n`, skipped };
}

export type WriteEnvResult = "created" | "updated" | "unchanged";

export class EnvFileConflictError extends Error {
	constructor(readonly path: string) {
		super(
			`${path} already exists and differs. Re-run with --yes to overwrite it.`,
		);
		this.name = "EnvFileConflictError";
	}
}

/**
 * .env を 0600 で書く。中身の違う既存のファイルは、overwrite が true のときだけ置き換える。
 */
export async function writeEnvFile(
	path: string,
	content: string,
	overwrite: boolean,
): Promise<WriteEnvResult> {
	let existing: string | undefined;
	try {
		existing = await readFile(path, "utf8");
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
	}
	if (existing === content) return "unchanged";
	if (existing !== undefined && !overwrite)
		throw new EnvFileConflictError(path);
	await writePrivateFile(path, content);
	return existing === undefined ? "created" : "updated";
}
